package com.example.lebiais.sonde

import com.example.lebiais.PointPixel
import com.example.lebiais.PositionGeo
import com.example.lebiais.ProjectionCadrage
import kotlin.math.log2

/** Ce que montre la carte : un centre et un zoom (fractionnaire). */
data class Cadrage(val centre: PositionGeo, val zoom: Double) {
    companion object {
        const val ZOOM_MIN = 5.0
        const val ZOOM_MAX = 17.0
    }
}

/**
 * Le doigt (ou la souris) s'est déplacé de ([dxPx], [dyPx]) : la carte suit,
 * donc le centre devient le point qui se trouvait à l'opposé du déplacement.
 */
fun Cadrage.glisse(dxPx: Double, dyPx: Double, largeurPx: Double, hauteurPx: Double): Cadrage {
    val projection = ProjectionCadrage(centre, zoom, largeurPx, hauteurPx)
    return copy(centre = projection.versGlobe(PointPixel(largeurPx / 2 - dxPx, hauteurPx / 2 - dyPx)))
}

/** Un pincement d'échelle [facteur] (2 = deux fois plus grand), zoom borné à [5 ; 17]. */
fun Cadrage.pince(facteur: Double): Cadrage =
    copy(zoom = (zoom + log2(facteur)).coerceIn(Cadrage.ZOOM_MIN, Cadrage.ZOOM_MAX))
