package com.example.lebiais.sonde

/**
 * Les règles de saisie de l'écran Saisie. Le clavier d'iOS n'est pas toujours
 * celui qu'on demande à une page web : on filtre donc aussi ce qui est tapé.
 */
object Saisies {
    fun numerique(texte: String): String = texte.filter { it in '0'..'9' }

    /** Chiffres et un seul séparateur, rendu en virgule. */
    fun decimal(texte: String): String {
        val sb = StringBuilder()
        var vu = false
        for (c in texte) when {
            c in '0'..'9' -> sb.append(c)
            (c == ',' || c == '.') && !vu -> { sb.append(','); vu = true }
        }
        return sb.toString()
    }

    /** Chiffres seulement, remis en jj/mm/aaaa, dix caractères au plus. */
    fun date(texte: String): String {
        val chiffres = numerique(texte).take(8)
        return buildString {
            chiffres.forEachIndexed { i, c ->
                if (i == 2 || i == 4) append('/')
                append(c)
            }
        }
    }

    /** Vide, ou une vraie date jj/mm/aaaa. */
    fun dateValide(texte: String): Boolean {
        if (texte.isEmpty()) return true
        val p = texte.split('/')
        if (p.size != 3 || p[0].length != 2 || p[1].length != 2 || p[2].length != 4) return false
        val j = p[0].toIntOrNull() ?: return false
        val m = p[1].toIntOrNull() ?: return false
        val a = p[2].toIntOrNull() ?: return false
        if (m !in 1..12 || j < 1) return false
        val bissextile = (a % 4 == 0 && a % 100 != 0) || a % 400 == 0
        val max = when (m) { 2 -> if (bissextile) 29 else 28; 4, 6, 9, 11 -> 30; else -> 31 }
        return j <= max
    }
}
