private val PASTILLES = listOf(Color(0xFFB5523B), Color(0xFF4F7A5A), Color(0xFF3F6E9A), Color(0xFFC59A2E), Color(0xFF7B5A8C))

/** Images par seconde, moyenne glissante sur une seconde. */
@Composable
fun rememberImagesParSeconde(): Int {
    var fps by remember { mutableStateOf(0) }
    LaunchedEffect(Unit) {
        var debut = 0L
        var n = 0
        while (true) {
            val t = withFrameNanos { it }
            if (debut == 0L) debut = t
            n++
            if (t - debut >= 1_000_000_000L) {
                fps = (n * 1_000_000_000L / (t - debut)).toInt()
                debut = t
                n = 0
            }
        }
    }
    return fps
}

/** 300 bêtes en `LazyColumn`, avec le compteur d'images par seconde. */
@Composable
fun EcranListe() {
    val betes = remember { troupeauFictif(300) }
    val fps = rememberImagesParSeconde()
    Column(Modifier.fillMaxSize()) {
        Text("$fps images/s · ${betes.size} bêtes", fontSize = 16.sp, modifier = Modifier.padding(16.dp))
        LazyColumn(Modifier.fillMaxSize()) {
            items(betes, key = { it.boucle }) { b ->
                Row(Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp)) {
                    Box(
                        Modifier.padding(top = 4.dp).size(14.dp).clip(CircleShape)
                            .background(PASTILLES[(b.boucle.hashCode() and 0x7fffffff) % PASTILLES.size]),
                    )
                    Column(Modifier.padding(start = 12.dp)) {
                        Text("${b.boucle} · ${b.nom}", fontSize = 16.sp)
                        Text(b.note, fontSize = 13.sp, maxLines = 2, overflow = TextOverflow.Ellipsis)
                    }
                }
            }
        }
    }
}
