private const val TUILES_EN_MEMOIRE = 200
private val FONDS = listOf(FondsDeCarte.IGN_PLAN, FondsDeCarte.OPENTOPO)

/** Une tuile gardée : son image, ou null quand elle a été refusée. */
private class Gardee(val image: ImageBitmap?)

/** La mémoire des tuiles : 200 au plus, la plus ancienne part la première. */
private class MemoireTuiles {
    private val gardees = LinkedHashMap<String, Gardee>()
    private val enCours = HashSet<String>()
    var version by mutableIntStateOf(0)
    var recues by mutableIntStateOf(0)
    var refusees by mutableIntStateOf(0)

    fun lire(cle: String): Gardee? = gardees[cle]
    fun demander(cle: String): Boolean = cle !in gardees && enCours.add(cle)

    fun ranger(cle: String, image: ImageBitmap?) {
        enCours.remove(cle)
        gardees[cle] = Gardee(image)
        if (image != null) recues++ else refusees++
        while (gardees.size > TUILES_EN_MEMOIRE) gardees.remove(gardees.keys.first())
        version++
    }
}

@Composable
fun EcranCarte() {
    var cadrage by remember { mutableStateOf(Cadrage(PositionGeo(45.2, 6.4), 13.0)) }
    var source by remember { mutableStateOf<SourceTuiles>(FONDS[0]) }
    var taille by remember { mutableStateOf(IntSize.Zero) }
    val memoire = remember { MemoireTuiles() }
    val telechargements = remember { Semaphore(6) }
    val scope = rememberCoroutineScope()
    val images = imagesParSecondeCarte()

    val l = taille.width.toDouble()
    val h = taille.height.toDouble()
    val z = floor(cadrage.zoom).toInt().coerceIn(source.zoomMin, source.zoomMax)
    val projection = ProjectionCadrage(cadrage.centre, cadrage.zoom, l, h)
    val visibles = GrilleTuiles.visibles(projection, l, h, z)

    // Les tuiles absentes partent au téléchargement, six à la fois.
    for (t in visibles) {
        val cle = cleDe(source, t)
        if (memoire.demander(cle)) {
            scope.launch {
                val image = telechargements.withPermit {
                    Navigateur.telechargerTuile(source.urlDe(t))?.let { Navigateur.decoderImage(it) }
                }
                memoire.ranger(cle, image)
            }
        }
    }

    Column(Modifier.fillMaxSize()) {
        Row(Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp)) {
            for (f in FONDS) {
                Text(
                    f.nom,
                    color = if (f == source) Color.White else Color(0xFF1F1B16),
                    fontSize = 14.sp,
                    modifier = Modifier
                        .background(if (f == source) Color(0xFF1F1B16) else Color(0xFFE8E0D0))
                        .clickable { source = f }
                        .padding(horizontal = 12.dp, vertical = 8.dp),
                )
                Text("", modifier = Modifier.padding(4.dp))
            }
        }
        Text(
            "$images images/s · tuiles reçues ${memoire.recues} · tuiles refusées ${memoire.refusees} · zoom ${(cadrage.zoom * 10).toInt() / 10.0} · ${source.mentionCourte}",
            fontSize = 13.sp,
            color = Color(0xFF1F1B16),
            modifier = Modifier.padding(horizontal = 16.dp, vertical = 4.dp),
        )
        Canvas(
            Modifier
                .fillMaxSize()
                .background(Color(0xFFDDD6C6))
                .clipToBounds()
                .onSizeChanged { taille = it }
                .pointerInput(Unit) {
                    detectTransformGestures { _, pan, zoom, _ ->
                        cadrage = cadrage.glisse(pan.x.toDouble(), pan.y.toDouble(), size.width.toDouble(), size.height.toDouble())
                            .pince(zoom.toDouble())
                    }
                }
                .pointerInput(Unit) {
                    // la molette : un cran (~100 px de défilement) = un tiers de niveau
                    awaitEachGesture {
                        while (true) {
                            val evenement = awaitPointerEvent()
                            if (evenement.type == PointerEventType.Scroll) {
                                val dy = evenement.changes.firstOrNull()?.scrollDelta?.y ?: 0f
                                if (dy != 0f) cadrage = cadrage.pince(2.0.pow(-dy / 300.0))
                                evenement.changes.forEach { it.consume() }
                            }
                        }
                    }
                },
        ) {
            memoire.version // relit le dessin quand une tuile arrive
            val echelle = 2.0.pow(cadrage.zoom - z)
            val centreMonde = WebMercator.versMonde(cadrage.centre, z.toDouble())
            val cote = (WebMercator.TAILLE_TUILE * echelle).toFloat()
            for (t in visibles) {
                val x = (l / 2 + (t.x * WebMercator.TAILLE_TUILE - centreMonde.x) * echelle).toFloat()
                val y = (h / 2 + (t.y * WebMercator.TAILLE_TUILE - centreMonde.y) * echelle).toFloat()
                val gardee = memoire.lire(cleDe(source, t)) ?: continue
                if (gardee.image != null) {
                    val entier = floor(cote + 1f).toInt()
                    drawImage(
                        gardee.image,
                        srcOffset = IntOffset.Zero,
                        srcSize = IntSize(gardee.image.width, gardee.image.height),
                        dstOffset = IntOffset(floor(x).toInt(), floor(y).toInt()),
                        dstSize = IntSize(entier, entier),
                    )
                } else {
                    // tuile refusée : un carré barré
                    val rouge = Color(0xFFB3261E)
                    drawRect(rouge, Offset(x + 2f, y + 2f), androidx.compose.ui.geometry.Size(cote - 4f, cote - 4f), style = Stroke(2f))
                    drawLine(rouge, Offset(x + 2f, y + 2f), Offset(x + cote - 2f, y + cote - 2f), 2f)
                    drawLine(rouge, Offset(x + cote - 2f, y + 2f), Offset(x + 2f, y + cote - 2f), 2f)
                }
            }
        }
    }
}

private fun cleDe(source: SourceTuiles, t: Tuile): String = "${source.id}/${t.cle}"

/** Images par seconde : moyenne sur une seconde, une image comptée par `withFrameNanos`. */
@Composable
private fun imagesParSecondeCarte(): Int {
    var fps by remember { mutableIntStateOf(0) }
    LaunchedEffect(Unit) {
        var debut = 0L
        var compte = 0
        while (true) {
            withFrameNanos { t ->
                if (debut == 0L) debut = t
                compte++
                if (t - debut >= 1_000_000_000L) {
                    fps = (compte * 1_000_000_000L / (t - debut)).toInt()
                    debut = t
                    compte = 0
                }
            }
        }
    }
    return fps
}
