package com.example.lebiais.sonde

/**
 * Un motif d'octets pseudo-aléatoire et déterministe : le même pour une graine
 * donnée, où qu'on le relise. Un xorshift32 est réinitialisé tous les 4096
 * octets (graine * 31 + rang / 4096) : on vérifie donc un morceau sans relire
 * le début.
 */
object Motif {
    private const val SEGMENT = 4096

    private fun depart(graine: Int, segment: Int): Int {
        val s = (graine * 31 + segment) xor 0x2545F491
        return if (s == 0) 1 else s
    }

    private fun suivant(x: Int): Int {
        var s = x
        s = s xor (s shl 13)
        s = s xor (s ushr 17)
        s = s xor (s shl 5)
        return s
    }

    private fun octetDe(etat: Int): Byte = (etat ushr 8).toByte()

    fun octet(graine: Int, rang: Int): Byte = bloc(graine, rang, 1)[0]

    fun bloc(graine: Int, debut: Int, taille: Int): ByteArray {
        val sortie = ByteArray(taille)
        var i = 0
        while (i < taille) {
            val rang = debut + i
            val segment = rang / SEGMENT
            var etat = depart(graine, segment)
            // Dérouler jusqu'à la position dans le segment, puis jusqu'à la fin de celui-ci.
            for (k in 0..(rang % SEGMENT)) etat = suivant(etat)
            val fin = minOf(taille, i + (SEGMENT - rang % SEGMENT))
            sortie[i++] = octetDe(etat)
            while (i < fin) {
                etat = suivant(etat)
                sortie[i++] = octetDe(etat)
            }
        }
        return sortie
    }

    /** Le rang du premier octet faux de [lu], lu à partir de [debut], ou null s'il est intact. */
    fun premierEcart(graine: Int, debut: Int, lu: ByteArray): Int? {
        val attendu = bloc(graine, debut, lu.size)
        for (i in lu.indices) if (lu[i] != attendu[i]) return debut + i
        return null
    }
}
