import androidx.compose.ui.ExperimentalComposeUiApi
import androidx.compose.ui.window.ComposeViewport
import com.example.lebiais.sonde.Sonde
import kotlinx.browser.document
import org.jetbrains.compose.resources.ExperimentalResourceApi
import org.jetbrains.compose.resources.configureWebResources

@OptIn(ExperimentalComposeUiApi::class, ExperimentalResourceApi::class)
fun main() {
    // La page est servie à la racine, les ressources sont rangées sous js/.
    configureWebResources { resourcePathMapping { chemin -> "js/$chemin" } }
    ComposeViewport(document.getElementById("ComposeTarget")!!) { Sonde() }
}
