package com.example.lebiais.sonde

import kotlin.io.encoding.Base64

// `Cadrage`, `glisse` et `pince` vivent dans :sondePwaLogique (essais Node sans Compose).

/** Les octets d'une chaîne base64 venue de sonde.js, ou null. */
internal fun octetsDepuisBase64(base64: String?): ByteArray? =
    if (base64.isNullOrEmpty()) null else Base64.decode(base64)

/** « type MIME\nbase64 » de sonde.js `choisirPhoto`. */
internal fun photoDepuisEchange(echange: String?): PhotoChoisie? {
    if (echange == null) return null
    val coupe = echange.indexOf('\n')
    if (coupe < 0) return null
    val octets = octetsDepuisBase64(echange.substring(coupe + 1)) ?: return null
    return PhotoChoisie(octets, echange.substring(0, coupe))
}
