package com.example.lebiais.sonde

import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.toComposeImageBitmap
import kotlinx.coroutines.await
import org.jetbrains.skia.Image
import kotlin.js.Promise

actual object Navigateur {
    // ---- Socle (tâche 2) ----
    actual val version: String = "js"
    actual fun estInstallee(): Boolean = js("window.sonde.estInstallee()") as Boolean
    actual fun margesSures(): MargesSures = MargesSures(marge("haut"), marge("bas"), marge("gauche"), marge("droite"))
    actual fun msDepuisLancement(): Double = js("window.sonde.msDepuisLancement()") as Double
    actual fun build(): String = js("window.sonde.build()") as String
    private fun marge(cote: String): Double = js("window.sonde.marge(cote)") as Double

    // ---- Stockage (tâche 3) ----
    actual val ecrivain: Ecrivain = object : Ecrivain {
        override suspend fun ecrire(nom: String, rang: Int, morceau: ByteArray) {
            val texte = octetsEnTexte(morceau)
            contenuDe((js("window.sonde.ecrireMorceau(nom, rang, texte)") as Promise<String>).await())
        }

        override suspend fun terminer(nom: String, reussi: Boolean) {
            contenuDe((js("window.sonde.terminerEcriture(nom, reussi)") as Promise<String>).await())
        }
    }
    actual suspend fun lireFichier(nom: String, parMorceau: (ByteArray) -> Unit): Resultat =
        lireParMorceaux(nom, parMorceau) { n, rang ->
            (js("window.sonde.lireMorceau(n, rang)") as Promise<String>).await()
        }
    actual suspend fun demanderPersistance(): String = (js("window.sonde.demanderPersistance()") as Promise<String>).await()
    actual suspend fun estimation(): String = (js("window.sonde.estimation()") as Promise<String>).await()
    actual fun moyenDeStockage(): String = js("window.sonde.moyenDeStockage()") as String
    actual fun graineDuJour(): Int = js("window.sonde.graineDuJour()") as Int
    actual fun graineEcrite(): Int = js("window.sonde.graineEcrite()") as Int
    actual fun dateDerniereEcriture(): String = js("window.sonde.dateDerniereEcriture()") as String
    actual fun noterDerniereEcriture(graine: Int) { js("window.sonde.noterDerniereEcriture(graine)") }
    actual fun oublierDerniereEcriture() { js("window.sonde.oublierDerniereEcriture()") }

    // ---- Carte et photos (tâche 5) ----
    private fun jsTuile(url: String): Promise<String?> = js("window.sonde.telechargerTuile(url)") as Promise<String?>
    private fun jsPhoto(capture: Boolean): Promise<String?> = js("window.sonde.choisirPhoto(capture)") as Promise<String?>
    actual suspend fun telechargerTuile(url: String): ByteArray? = try { octetsDepuisBase64(jsTuile(url).await()) } catch (e: Throwable) { null }
    actual suspend fun choisirPhoto(capture: Boolean): PhotoChoisie? = photoDepuisEchange(jsPhoto(capture).await())
    actual fun decoderImage(octets: ByteArray): ImageBitmap? = try { Image.makeFromEncoded(octets).toComposeImageBitmap() } catch (e: Throwable) { null }

    // ---- Coque installable (tâche 6) ----
    actual fun userAgent(): String = js("window.sonde.userAgent()") as String
    actual fun ouvertureMemorisee(): String = js("window.sonde.ouvertureMemorisee()") as String
    actual fun noterOuverture(ms: Double) { js("window.sonde.noterOuverture(ms)") }
    actual suspend fun persistanceActuelle(): String = (js("window.sonde.persistanceActuelle()") as Promise<String>).await()
    actual suspend fun etatServiceWorker(): String = (js("window.sonde.etatServiceWorker()") as Promise<String>).await()
    actual fun recharger() { js("window.sonde.recharger()") }
    actual fun modeClavier(inputMode: String, autoCapitalize: String) { js("window.sonde.modeClavier(inputMode, autoCapitalize)") }
    actual fun hauteurClavier(): Double = js("window.sonde.hauteurClavier()") as Double
    actual fun mesuresClavier(): String = js("window.sonde.mesuresClavier()") as String
}
